for (const item of $input.all()) {
  const perfil = item.json.perfil;
  let recomendacao = '';

  if (perfil === 'Conservador') {
    recomendacao = 'Foco em renda fixa e segurança (Tesouro Direto, CDBs de liquidez diária).';
  } else if (perfil === 'Moderado') {
    recomendacao = 'Mix equilibrado entre renda fixa e fundos imobiliários/ações.';
  } else if (perfil === 'Arrojado') {
    recomendacao = 'Ênfase em ações, criptoativos e maior potencial de retorno de longo prazo.';
  } else {
    recomendacao = 'Perfil não mapeado.';
  }

  item.json.recomendacao = recomendacao;
}
return $input.all();
